import sys
input = sys.stdin.readline

def readList():
	return list(map(int, input().split()))

def readInt():
	return int(input())

def readInts():
	return map(int, input().split())

def readStr():
	return input().strip()

def solve():
	n = readInt()
	arr = readList()
	V = max(arr)
	if n > 3:
		return n * V
	elif n == 2:
		return max(sum(arr), abs(arr[0] - arr[1]) * 2)
	else:
		return max(sum(arr), 3 * arr[0], 3 * arr[-1], 3 * abs(arr[0] - arr[1]), 3 * abs(arr[1] - arr[-1]))
for _ in range(int(input())):
	print(solve())
